```matlab
Nsim = 60; y = zeros(1,Nsim); u = zeros(1,Nsim); e = zeros(1,Nsim);
for k = 5:Nsim
    y(k) = 0.8669*y(k-1) + 0.1331*u(k-4);
    e(k) = 1.0 - y(k);
    % 原大林: u(k) = 0.7788*u(k-1) + 0.2212*u(k-4) + 1.6619*e(k) - 1.4407*e(k-1);
    % 消振铃: 
    u(k) = u(k-1) + 0.9989*e(k) - 0.8659*e(k-1);
end
```

MATLAB 仿真程序（采用差分递推并注释全部变量）：
```matlab
clear; clc;
T = 1; N = 30;                  % T: 采样周期(s); N: 仿真总拍数
t = 0:T:(N-1)*T;                % t: 离散时间向量
r = ones(1, N);                 % r: 单位阶跃参考输入序列
y = zeros(1, N);                % y: 被控对象输出序列
u = zeros(1, N);                % u: 控制器输出(控制量)序列
e = zeros(1, N);                % e: 闭环误差序列
for k = 1:N
    y1 = (k>1)*y(max(k-1,1)); y2 = (k>2)*y(max(k-2,1));
    u3 = (k>3)*u(max(k-3,1)); u4 = (k>4)*u(max(k-4,1));
    y(k) = 1.6214*y1 - 0.6483*y2 + 0.02892*u3 + 0.02503*u4;
    e(k) = r(k) - y(k);
    e1 = (k>1)*e(max(k-1,1)); e2 = (k>2)*e(max(k-2,1));
    u1 = (k>1)*u(max(k-1,1)); u2 = (k>2)*u(max(k-2,1));
    u(k) = -0.08674*u1 + 0.6741*u2 + 0.2212*u3 + 0.1915*u4 ...
           + 7.6487*e(k) - 12.4013*e1 + 4.9590*e2;
end
subplot(2,2,1); stairs(t, r); title('参考输入 r(k)'); grid on;
subplot(2,2,2); stairs(t, u); title('控制量 u(k)'); grid on;
subplot(2,2,3); stairs(t, y); title('被控量 y(k)'); grid on;
subplot(2,2,4); stairs(t, e); title('误差 e(k)'); grid on;
```

